import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;
import java.math.BigDecimal;
public class Main extends JFrame {
 final Connection db; final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Produto","Categoria","Fornecedor","Preço (R$)","Quantidade","Mínimo"},0){public boolean isCellEditable(int r,int c){return false;}};
 final JTable table=new JTable(model); final JLabel resumo=new JLabel();
 public static void main(String[] args){SwingUtilities.invokeLater(()->{try{new Main().setVisible(true);}catch(Exception e){JOptionPane.showMessageDialog(null,e.toString());}});}
 Main() throws Exception {db=DriverManager.getConnection("jdbc:sqlite:estoque.db");try(Statement s=db.createStatement()){s.execute("CREATE TABLE IF NOT EXISTS produtos(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,categoria TEXT,fornecedor TEXT,preco INTEGER CHECK(preco>=0),qtd INTEGER CHECK(qtd>=0),minimo INTEGER CHECK(minimo>=0))");s.execute("CREATE TABLE IF NOT EXISTS movimentos(id INTEGER PRIMARY KEY,produto TEXT,tipo TEXT,qtd INTEGER,data TEXT DEFAULT CURRENT_TIMESTAMP)");}setTitle("Delooe | Gestão de Estoque");setSize(1000,550);setLocationRelativeTo(null);setDefaultCloseOperation(EXIT_ON_CLOSE);JPanel top=new JPanel();for(String a:new String[]{"Cadastrar","Editar","Excluir","Entrada","Saída","Histórico","Atualizar"}){JButton b=new JButton(a);top.add(b);b.addActionListener(e->{try{switch(a){case "Cadastrar"->editar(false);case "Editar"->editar(true);case "Excluir"->excluir();case "Entrada"->movimento(true);case "Saída"->movimento(false);case "Histórico"->historico();}atualizar();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}});}add(top,BorderLayout.NORTH);add(new JScrollPane(table));add(resumo,BorderLayout.SOUTH);atualizar();}
 int linha(){int r=table.getSelectedRow();if(r<0)throw new IllegalArgumentException("Selecione um produto.");return r;}
 void editar(boolean edit)throws Exception{int r=edit?linha():-1;String[] labels={"Nome","Categoria","Fornecedor","Preço em reais","Quantidade inicial","Estoque mínimo"};JTextField[] f=new JTextField[6];JPanel p=new JPanel(new GridLayout(6,2));for(int i=0;i<6;i++){f[i]=new JTextField(edit?model.getValueAt(r,i+1).toString():i>=3?"0":"");p.add(new JLabel(labels[i]));p.add(f[i]);}if(edit)f[4].setEditable(false);if(JOptionPane.showConfirmDialog(this,p,"Produto",JOptionPane.OK_CANCEL_OPTION)!=0)return;String nome=f[0].getText().trim();long preco=new BigDecimal(f[3].getText().replace(',','.')).movePointRight(2).longValueExact();int qtd=Integer.parseInt(f[4].getText()),min=Integer.parseInt(f[5].getText());if(nome.isEmpty()||preco<0||qtd<0||min<0)throw new IllegalArgumentException("Dados inválidos.");try(PreparedStatement s=db.prepareStatement(edit?"UPDATE produtos SET nome=?,categoria=?,fornecedor=?,preco=?,qtd=?,minimo=? WHERE id=?":"INSERT INTO produtos(nome,categoria,fornecedor,preco,qtd,minimo) VALUES(?,?,?,?,?,?)")){s.setString(1,nome);s.setString(2,f[1].getText());s.setString(3,f[2].getText());s.setLong(4,preco);s.setInt(5,qtd);s.setInt(6,min);if(edit)s.setInt(7,(Integer)model.getValueAt(r,0));s.executeUpdate();}}
 void excluir()throws Exception{int r=linha();if(JOptionPane.showConfirmDialog(this,"Excluir produto?","Confirmar",JOptionPane.YES_NO_OPTION)!=0)return;try(PreparedStatement s=db.prepareStatement("DELETE FROM produtos WHERE id=?")){s.setInt(1,(Integer)model.getValueAt(r,0));s.executeUpdate();}}
 void movimento(boolean entrada)throws Exception{int r=linha();String v=JOptionPane.showInputDialog(this,"Quantidade:");if(v==null)return;int n=Integer.parseInt(v),atual=(Integer)model.getValueAt(r,5);if(n<=0||(!entrada&&n>atual))throw new IllegalArgumentException("Quantidade inválida ou estoque insuficiente.");db.setAutoCommit(false);try(PreparedStatement s=db.prepareStatement("UPDATE produtos SET qtd=? WHERE id=?");PreparedStatement h=db.prepareStatement("INSERT INTO movimentos(produto,tipo,qtd) VALUES(?,?,?)")){s.setInt(1,entrada?Math.addExact(atual,n):atual-n);s.setInt(2,(Integer)model.getValueAt(r,0));s.executeUpdate();h.setString(1,model.getValueAt(r,1).toString());h.setString(2,entrada?"Entrada":"Saída");h.setInt(3,n);h.executeUpdate();db.commit();}catch(Exception e){db.rollback();throw e;}finally{db.setAutoCommit(true);}}
 void atualizar()throws Exception{model.setRowCount(0);long unidades=0,baixo=0;BigDecimal total=BigDecimal.ZERO;try(Statement s=db.createStatement();ResultSet r=s.executeQuery("SELECT * FROM produtos ORDER BY nome")){while(r.next()){int q=r.getInt("qtd"),m=r.getInt("minimo");BigDecimal p=BigDecimal.valueOf(r.getLong("preco"),2);model.addRow(new Object[]{r.getInt("id"),r.getString("nome"),r.getString("categoria"),r.getString("fornecedor"),p.toPlainString(),q,m});unidades+=q;if(q<=m)baixo++;total=total.add(p.multiply(BigDecimal.valueOf(q)));}}resumo.setText("  Produtos: "+model.getRowCount()+" | Unidades: "+unidades+" | Estoque baixo: "+baixo+" | Valor total: R$ "+total);}
 void historico()throws Exception{JTextArea t=new JTextArea(18,60);t.setEditable(false);try(Statement s=db.createStatement();ResultSet r=s.executeQuery("SELECT * FROM movimentos ORDER BY id DESC")){while(r.next())t.append(r.getString("data")+" | "+r.getString("produto")+" | "+r.getString("tipo")+" | "+r.getInt("qtd")+"\n");}JOptionPane.showMessageDialog(this,new JScrollPane(t),"Histórico (UTC)",JOptionPane.PLAIN_MESSAGE);}
}
